'use client'

import type { ComponentProps } from 'react'
import { useState } from 'react'
import { Avatar, AvatarFallback, AvatarImage } from '@astrale-os/ui/avatar'
import { Badge } from '@astrale-os/ui/badge'
import { Button } from '@astrale-os/ui/button'
import { Card, CardContent } from '@astrale-os/ui/card'
import { Progress } from '@astrale-os/ui/progress'
import { Separator } from '@astrale-os/ui/separator'
import {
  Kanban,
  KanbanBoard,
  KanbanColumn,
  KanbanColumnContent,
  KanbanColumnHandle,
  KanbanItem,
  KanbanItemHandle,
  KanbanOverlay
} from '@/components/ui/kanban'

import { cn } from '@astrale-os/ui/class-name'
import { CalendarClockIcon, GripVerticalIcon } from "lucide-react"

type ColumnId = 'intake' | 'execution' | 'release'
type Health = 'onTrack' | 'atRisk' | 'blocked'

interface Initiative {
  id: string
  title: string
  area: string
  progress: number
  dueDate: string
  health: Health
  owner: {
    name: string
    avatar: string
    initials: string
  }
}

const COLUMN_META: Record<ColumnId, { title: string; accent: string }> = {
  intake: {
    title: 'Intake',
    accent: 'bg-sky-600 dark:bg-sky-400'
  },
  execution: {
    title: 'Execution',
    accent: 'bg-amber-600 dark:bg-amber-400'
  },
  release: {
    title: 'Release',
    accent: 'bg-green-600 dark:bg-green-400'
  }
}

const HEALTH_META: Record<
  Health,
  { label: string; variant: ComponentProps<typeof Badge>['variant']; className: string }
> = {
  onTrack: {
    label: 'On track',
    variant: 'outline',
    className: 'border-green-600/50 text-green-600 dark:border-green-400/50 dark:text-green-400'
  },
  atRisk: {
    label: 'At risk',
    variant: 'outline',
    className: 'border-destructive text-destructive'
  },
  blocked: {
    label: 'Blocked',
    variant: 'destructive',
    className: 'border-transparent'
  }
}

const INITIAL_COLUMNS: Record<ColumnId, Initiative[]> = {
  intake: [
    {
      id: 'initiative-1',
      title: 'Customer health dashboard',
      area: 'Analytics',
      progress: 18,
      dueDate: 'Jul 08',
      health: 'onTrack',
      owner: {
        name: 'Alex Johnson',
        avatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-1.png',
        initials: 'AJ'
      }
    },
    {
      id: 'initiative-2',
      title: 'Usage limit notifications',
      area: 'Growth',
      progress: 12,
      dueDate: 'Jul 12',
      health: 'atRisk',
      owner: {
        name: 'Sarah Chen',
        avatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-2.png',
        initials: 'SC'
      }
    },
    {
      id: 'initiative-3',
      title: 'Team audit log export',
      area: 'Admin',
      progress: 38,
      dueDate: 'Jul 18',
      health: 'onTrack',
      owner: {
        name: 'Emma Wilson',
        avatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-3.png',
        initials: 'EW'
      }
    },
    {
      id: 'initiative-4',
      title: 'New billing plan cards',
      area: 'Billing',
      progress: 44,
      dueDate: 'Jul 20',
      health: 'onTrack',
      owner: {
        name: 'Michael Rodriguez',
        avatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-4.png',
        initials: 'MR'
      }
    }
  ],
  execution: [
    {
      id: 'initiative-5',
      title: 'Role based navigation',
      area: 'Platform',
      progress: 67,
      dueDate: 'Jul 24',
      health: 'atRisk',
      owner: {
        name: 'David Kim',
        avatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-5.png',
        initials: 'DK'
      }
    },
    {
      id: 'initiative-6',
      title: 'Workspace invite refresh',
      area: 'Identity',
      progress: 72,
      dueDate: 'Jul 26',
      health: 'blocked',
      owner: {
        name: 'Nina Patel',
        avatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-6.png',
        initials: 'NP'
      }
    }
